probe_script:
import json, glob, re, subprocess, collections, sys

# 青空文庫URLを持つ素材の「指し示し」が、記された作品へ解決するかの測定（読み取り専用）。
# 台帳は変更しない。GitHub上の二つの固定版ミラーだけを使う（gh CLI が必要）。
T, TS = "aozorahack/aozorabunko_text", "0984f7dc18a2270bdfd2ff99bf14fd1b3ebb4f65"
H, HS = "takahashim/aozorabunko_html", "de24369241d095792a8fb3af9155df231df9baae"
OUT = sys.argv[1] if len(sys.argv) > 1 else None

# 解決した題が素材の題と字面で一致しないが、収録作品として対応するもの（手作業の判定。理由つき）。
CONTAINED = {
    "MAT-LIT-007": "序は詩集『春と修羅』の一部",
    "MAT-LIT-20261024-c2dc67": "「永訣の朝」は詩集『春と修羅』所収",
    "MAT-LIT-108": "「言葉なき歌」は『在りし日の歌』所収",
    "MAT-LIT-057": "序は『古事記』の一部",
    "MAT-LIT-025": "冒頭等は『土佐日記』の一部",
    "MAT-LIT-009": "草庵の記等は『方丈記』の一部",
    "MAT-LIT-014": "我を愛する歌は『一握の砂』の一部",
    "MAT-LIT-076": "句集『草木塔』",
    "MAT-LIT-109": "「竹」は『月に吠える』所収",
    "MAT-LIT-292": "『方丈記』本文",
    "MAT-LIT-003": "下篇は『こころ』の一部",
}
# 解決したが別作品を指すもの（手作業の判定。解決先の題を併記）。
MISMATCH = {
    "MAT-LIT-030": "或阿呆の一生 → 地獄変",
    "MAT-LIT-255": "こころ → 吾輩は猫である",
    "MAT-LIT-20261024-032442": "竹取物語 → 闇の絵巻（梶井基次郎）",
    "MAT-LIT-20261024-b2d804": "大つごもり → たけくらべ（同著者の388が大つごもり）",
    "MAT-LIT-20261024-f7a85d": "雨ニモマケズ → 銀河鉄道の夜",
    "MAT-LIT-20261024-00fafe": "それから → 硝子戸の中",
    "MAT-LIT-20261024-9e71d8": "おくのほそ道 → 桜の樹の下には（梶井基次郎）",
    "MAT-LIT-20261024-590aad": "門 → ケーベル先生の告別",
    "MAT-LIT-467": "夢十夜 → 硝子戸の中",
    "MAT-LIT-493": "藪の中 → 羅生門（既知：ERR-20261119-b3a9ec）",
    "MAT-20261024-ed83a9": "紫式部日記 → 源氏物語 桐壺",
    "MAT-20261024-2ee91d": "源氏物語「梅枝」 → 源氏物語「末摘花」（帖の不一致）",
}

def gh(path, raw=False):
    cmd = ["gh", "api", path] + (["-H", "Accept: application/vnd.github.raw"] if raw else [])
    return subprocess.run(cmd, capture_output=True)

def dec(b):
    for e in ("utf-8", "cp932", "euc-jp"):
        try:
            return b.decode(e)
        except UnicodeDecodeError:
            pass
    return b.decode("utf-8", "replace")

def jl(pat):
    rows = []
    for f in sorted(glob.glob(pat)):
        for line in open(f, encoding="utf-8"):
            line = line.strip()
            if line:
                rows.append(json.loads(line))
    return rows

mats = jl("state/materials.jsonl") + jl("state/materials.d/*.jsonl")
eds = {}
for d in jl("state/editorial_decisions.jsonl") + jl("state/editorial_decisions.d/*.jsonl"):
    if d["target"]["type"] == "material":
        eds[d["target"]["id"]] = d["status"]
pop = []
for r in mats:
    url = (r.get("source") or {}).get("url") or ""
    m = re.search(r"aozora\.gr\.jp/cards/(\d+)/(?:card(\d+)\.html|files/(\d+)_)", url)
    if m:
        st = eds.get(r["material_id"], (r.get("verification") or {}).get("status"))
        pop.append(dict(material_id=r["material_id"], title=r.get("title", ""), url=url,
                        author_card=m.group(1), work=m.group(2) or m.group(3), status=st))

tdir, hdir = {}, {}
for p in pop:
    a, w = p["author_card"], p["work"]
    if a not in tdir:
        o = gh(f"repos/{T}/contents/cards/{a}/files?ref={TS}")
        try:
            tdir[a] = [i["name"] for i in json.loads(o.stdout) if isinstance(i, dict)]
        except Exception:
            tdir[a] = None
    hit = [n for n in (tdir[a] or []) if n.split("_")[0] == w]
    p["resolved_title"], p["route"] = None, None
    if hit:
        o = gh(f"repos/{T}/contents/cards/{a}/files/{hit[0]}?ref={TS}")
        try:
            txt = [i["path"] for i in json.loads(o.stdout) if i["name"].endswith(".txt")]
        except Exception:
            txt = []
        if txt:
            lines = dec(gh(f"repos/{T}/contents/{txt[0]}?ref={TS}", raw=True).stdout).replace("\r", "").split("\n")
            p["resolved_title"] = " / ".join(x for x in lines[:3] if x.strip())[:80]
            p["route"] = f"https://github.com/{T}/blob/{TS}/{txt[0]}"
    if p["route"] is None:
        if a not in hdir:
            o = gh(f"repos/{H}/contents/cards/{a}/files?ref={HS}")
            try:
                hdir[a] = [i["name"] for i in json.loads(o.stdout) if isinstance(i, dict)]
            except Exception:
                hdir[a] = None
        hh = [n for n in (hdir[a] or []) if n.split("_")[0] == w or n.split(".")[0] == w]
        if hh:
            t = dec(gh(f"repos/{H}/contents/cards/{a}/files/{hh[0]}?ref={HS}", raw=True).stdout)
            mm = re.search(r"<title>(.*?)</title>", t, re.S)
            p["resolved_title"] = ("HTML: " + (mm.group(1).strip() if mm else ""))[:80]
            p["route"] = f"https://github.com/{H}/blob/{HS}/cards/{a}/files/{hh[0]}"
    if p["route"] is None:
        p["class"] = "unresolved"
    elif p["material_id"] in MISMATCH:
        p["class"] = "resolves_to_other_work"
        p["judgment"] = MISMATCH[p["material_id"]]
    else:
        p["class"] = "resolves_to_claimed_work"
        if p["material_id"] in CONTAINED:
            p["judgment"] = CONTAINED[p["material_id"]]

cls = collections.Counter(p["class"] for p in pop)
by_status = collections.Counter((p["status"] or "none", p["class"]) for p in pop)
nonverified_reachable = [p["material_id"] for p in pop
                         if p["class"] == "resolves_to_claimed_work" and p["status"] != "verified"]
res = dict(
    measured_on="2026-11-27",
    population="state/materials* の source.url が aozora.gr.jp/cards/<作家>/(card<N>.html|files/<N>_) に一致する素材",
    mirrors={"text": f"{T}@{TS}", "html": f"{H}@{HS}"},
    n=len(pop), classes=dict(cls),
    by_status={f"{k[0]}|{k[1]}": v for k, v in sorted(by_status.items())},
    nonverified_resolving_to_claimed_work=len(nonverified_reachable),
    caveats=["unresolved はミラーにカード番号の作品ファイルが無いことを示すだけで、URLの誤りを確定しない（ミラーの欠落、外字・XHTML専用作品の可能性）",
             "題の一致・不一致は解決先の冒頭行と素材の題を手作業で対応づけた判定（CONTAINED/MISMATCH）",
             "素材本文（passage）の正しさは測っていない"],
    rows=pop,
)
print(json.dumps({k: v for k, v in res.items() if k != "rows"}, ensure_ascii=False, indent=1))
if OUT:
    json.dump(res, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    open(OUT, "a").write("\n")
